import os, re, subprocess

ROOT = "/bench/repo"
# Persistent entity types - main struct types in store that represent DB tables
ENTITIES = [
    "Attachment", "Memo", "MemoRelation", "InstanceSetting", "User", 
    "UserSetting", "IdentityProvider", "Inbox", "Reaction", "MemoShare", "UserIdentity"
]

def get_go_packages(root, exclude_prefixes):
    """Find all Go packages and their files"""
    packages = {}
    for dirpath, dirnames, filenames in os.walk(root):
        go_files = [f for f in filenames if f.endswith('.go') and not f.endswith('_test.go')]
        if not go_files:
            continue
        rel = os.path.relpath(dirpath, root)
        if rel == '.':
            rel = ''
        # skip excluded
        skip = False
        for ex in exclude_prefixes:
            if rel == ex or rel.startswith(ex + '/'):
                skip = True
                break
        if skip:
            continue
        packages[dirpath] = go_files
    return packages

packages = get_go_packages(ROOT, ['store', 'proto'])

for entity in ENTITIES:
    pattern = re.compile(r'\bstore\.' + entity + r'\b')
    refs = set()
    for pkg_dir, files in packages.items():
        for fn in files:
            path = os.path.join(pkg_dir, fn)
            with open(path) as f:
                content = f.read()
            if pattern.search(content):
                refs.add(os.path.relpath(pkg_dir, ROOT))
                break
        # also check test files
        for fn in os.listdir(pkg_dir):
            if fn.endswith('_test.go'):
                path = os.path.join(pkg_dir, fn)
                with open(path) as f:
                    content = f.read()
                if pattern.search(content):
                    refs.add(os.path.relpath(pkg_dir, ROOT))
                    break
    print(f"{entity}: {len(refs)}")
    for r in sorted(refs):
        print(f"  {r}")
    print()
PYEOF

